import { useEffect, useState } from "react";
import EmployeeService from "../Services/EmployeeService";
import { useNavigate, useParams } from "react-router-dom";

const CreateOrUpdateEmployee = () => {
    const navigate = useNavigate();
    const { id } = useParams();
    const isNew = id === '_add';
    const [firstName, setFirstName] = useState("");
    const [lastName, setLastName] = useState("");
    const [email, setEmail] = useState("");

    const saveOrUpdateEmployee = (e) => {
        e.preventDefault();
        const employee = { firstName, lastName, email };
        if (isNew) {
            EmployeeService.createEmployee(employee).then(() => navigate("/"));
        } else {
            EmployeeService.updateEmployee(id, employee).then(() => navigate("/"));
        }
    };

    useEffect(() => {
        if (isNew) return;
        EmployeeService.getEmployeeById(id).then(res => {
            const emp = res.data;
            setFirstName(emp.firstName);
            setLastName(emp.lastName);
            setEmail(emp.email);
        }).catch(err => console.log(err));
    }, []);

    const inputStyle = { borderRadius: '6px', border: '1px solid #ced4da', padding: '10px 14px', fontSize: '15px', width: '100%', marginTop: '6px' };
    const labelStyle = { fontSize: '14px', fontWeight: '600', color: '#000' };

    return (
        <div style={{ minHeight: '50vh', background: '#e9ecef', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <div style={{ background: '#fff', borderRadius: '8px', padding: '40px', width: '100%', maxWidth: '460px', boxShadow: '0 4px 20px rgba(0,0,0,0.1)' }}>

                <div style={{ textAlign: 'center', marginBottom: '28px' }}>
                    <div style={{ background: '#212529', borderRadius: '50%', width: '56px', height: '56px', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 14px' }}>
                        <i className={`fa ${isNew ? 'fa-user-plus' : 'fa-user-edit'}`} style={{ color: '#fff', fontSize: '22px' }}></i>
                    </div>
                    <h4 style={{ fontWeight: '700', color: '#000', margin: 0 }}>{isNew ? 'Add Employee' : 'Update Employee'}</h4>
                    <small style={{ color: '#6c757d' }}>{isNew ? 'Fill in the details to add a new employee' : 'Modify the details below'}</small>
                </div>

                <form onSubmit={saveOrUpdateEmployee}>
                    <div style={{ marginBottom: '16px' }}>
                        <label style={labelStyle}>First Name</label>
                        <input type="text" placeholder="Enter first name" className="form-control" style={inputStyle} value={firstName} onChange={e => setFirstName(e.target.value)} required />
                    </div>
                    <div style={{ marginBottom: '16px' }}>
                        <label style={labelStyle}>Last Name</label>
                        <input type="text" placeholder="Enter last name" className="form-control" style={inputStyle} value={lastName} onChange={e => setLastName(e.target.value)} required />
                    </div>
                    <div style={{ marginBottom: '24px' }}>
                        <label style={labelStyle}>Email</label>
                        <input type="email" placeholder="Enter email" className="form-control" style={inputStyle} value={email} onChange={e => setEmail(e.target.value)} required />
                    </div>

                    <div style={{ display: 'flex', gap: '12px' }}>
                        <button type="submit" style={{ flex: 1, background: '#212529', color: '#fff', border: 'none', padding: '12px', borderRadius: '6px', fontSize: '15px', fontWeight: '600', cursor: 'pointer' }}>
                            <i className="fa fa-save me-2"></i>{isNew ? 'Save' : 'Update'}
                        </button>
                        <button type="button" onClick={() => navigate("/")} style={{ flex: 1, background: '#e9ecef', color: '#000', border: '1px solid #ced4da', padding: '12px', borderRadius: '6px', fontSize: '15px', fontWeight: '600', cursor: 'pointer' }}>
                            <i className="fa fa-times me-2"></i>Cancel
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
};

export default CreateOrUpdateEmployee;
